import EditMenuItem from './pages/menu/EditMenuItem';
import MenuItemList from './pages/menu/MenuItemList'; // For public view

function App() {
  return (
    <Router>
      {/* <nav style={{ marginBottom: "30px", textAlign: "center" }}>
