        <Link to="/login" style={{ textDecoration: "none", color: "#ff69b4" }}>Login</Link>
      </nav> */}

      <Routes>
        <Route path="/register" element={<RegisterPage />} />
        <Route path="/login" element={<LoginPage />} />
      </Routes>
    </Router>
  );
}

export default App;

